const vips = $input.all().map(i => String(i.json.domain || '').toLowerCase().trim()).filter(Boolean);
const mail = $('Watch Every Inbound Mail').first().json;
const address = ((mail.from && mail.from.value && mail.from.value[0].address) || '').toLowerCase();
const domain = address.split('@')[1] || '';
const hit = vips.find(v => domain === v || domain.endsWith('.' + v)) || '';
return [{ json: {
  isVip: Boolean(hit),
  matchedDomain: hit,
  address,
  senderName: (mail.from && mail.from.value && mail.from.value[0].name) || address,
  subject: mail.subject || '(no subject)',
  preview: String(mail.text || '').replace(/\s+/g, ' ').slice(0, 200),
} }];
